// Prepared native acceptance: requires the root-owned paired fixture contract.
using System;using System.Diagnostics;using System.IO;using System.Text;using System.Threading;using System.Runtime.InteropServices;using System.Collections.Generic;using System.Web.Script.Serialization;
class PairedParentCrashObserver {
 [StructLayout(LayoutKind.Sequential)]struct SA{public int size;public IntPtr descriptor;public int inherit;}
 [StructLayout(LayoutKind.Sequential,CharSet=CharSet.Unicode)]struct SI{public int cb;public string reserved,desktop,title;public uint x,y,xs,ys,xc,yc,fill,flags;public short show,reserved2;public IntPtr r2,input,output,error;}
 [StructLayout(LayoutKind.Sequential)]struct SIX{public SI startup;public IntPtr attributes;}
 [StructLayout(LayoutKind.Sequential)]struct PI{public IntPtr process,thread;public uint pid,tid;}
 [StructLayout(LayoutKind.Sequential)]struct Basic{public long a,b;public uint flags;public UIntPtr min,max;public uint active;public UIntPtr affinity;public uint priority,schedule;}
 [StructLayout(LayoutKind.Sequential)]struct Io{public ulong a,b,c,d,e,f;}
 [StructLayout(LayoutKind.Sequential)]struct Limits{public Basic basic;public Io io;public UIntPtr p,j,pp,pj;}
 [StructLayout(LayoutKind.Sequential)]struct Accounting{public long a,b,c,d;public uint faults,total,active,terminated;}
 [DllImport("kernel32.dll",SetLastError=true)]static extern bool GetProcessTimes(IntPtr h,out long created,out long exited,out long kernel,out long user);
 [DllImport("kernel32.dll",SetLastError=true)]static extern bool TerminateProcess(IntPtr h,uint code);
 [DllImport("kernel32.dll")]static extern uint WaitForSingleObject(IntPtr h,uint ms);
 [DllImport("kernel32.dll")]static extern bool GetExitCodeProcess(IntPtr h,out uint code);
 [DllImport("kernel32.dll")]static extern bool CloseHandle(IntPtr h);
 [DllImport("kernel32.dll",SetLastError=true)]static extern bool CreatePipe(out IntPtr reader,out IntPtr writer,ref SA attributes,uint size);
 [DllImport("kernel32.dll",SetLastError=true)]static extern bool SetHandleInformation(IntPtr h,uint mask,uint flags);
 [DllImport("kernel32.dll",SetLastError=true)]static extern bool PeekNamedPipe(IntPtr h,IntPtr buffer,uint size,IntPtr read,out uint available,IntPtr left);
 [DllImport("kernel32.dll",SetLastError=true)]static extern bool ReadFile(IntPtr h,byte[] b,uint size,out uint read,IntPtr overlap);
 [DllImport("kernel32.dll",CharSet=CharSet.Unicode,SetLastError=true)]static extern IntPtr CreateFileW(string path,uint access,uint share,ref SA attributes,uint creation,uint flags,IntPtr template);
 [DllImport("kernel32.dll",CharSet=CharSet.Unicode,SetLastError=true)]static extern bool CreateProcessW(string exe,StringBuilder command,IntPtr pa,IntPtr ta,bool inherit,uint flags,IntPtr environment,string cwd,ref SIX startup,out PI pi);
 [DllImport("kernel32.dll",SetLastError=true)]static extern bool InitializeProcThreadAttributeList(IntPtr list,int count,int flags,ref IntPtr bytes);
 [DllImport("kernel32.dll",SetLastError=true)]static extern bool UpdateProcThreadAttribute(IntPtr list,uint flags,IntPtr key,IntPtr value,IntPtr size,IntPtr previous,IntPtr returned);
 [DllImport("kernel32.dll")]static extern void DeleteProcThreadAttributeList(IntPtr list);
 [DllImport("kernel32.dll")]static extern uint ResumeThread(IntPtr h);
 [DllImport("kernel32.dll")]static extern IntPtr CreateJobObject(IntPtr a,string name);
 [DllImport("kernel32.dll")]static extern bool SetInformationJobObject(IntPtr job,int kind,ref Limits info,uint size);
 [DllImport("kernel32.dll")]static extern bool AssignProcessToJobObject(IntPtr job,IntPtr child);
 [DllImport("kernel32.dll")]static extern bool TerminateJobObject(IntPtr job,uint code);
 [DllImport("kernel32.dll")]static extern bool QueryInformationJobObject(IntPtr job,int kind,out Accounting info,uint size,IntPtr returned);
 [DllImport("user32.dll",CharSet=CharSet.Unicode,SetLastError=true)]static extern IntPtr CreateDesktop(string name,IntPtr device,IntPtr mode,uint flags,uint access,IntPtr security);
 [DllImport("user32.dll")]static extern bool CloseDesktop(IntPtr h);
 [DllImport("user32.dll")]static extern IntPtr OpenInputDesktop(uint flags,bool inherit,uint access);
 [DllImport("user32.dll",CharSet=CharSet.Unicode)]static extern bool GetUserObjectInformation(IntPtr h,int kind,StringBuilder name,uint size,out uint needed);
 static void Check(bool ok,string fixedReason){if(!ok)throw new Exception(fixedReason);}
 static string Input(){IntPtr h=OpenInputDesktop(0,false,1);Check(h!=IntPtr.Zero,"Input desktop query");try{var b=new StringBuilder(256);uint n;Check(GetUserObjectInformation(h,2,b,512,out n),"Input name query");return b.ToString();}finally{CloseDesktop(h);}}
 static long Creation(IntPtr h){long c,e,k,u;Check(GetProcessTimes(h,out c,out e,out k,out u)&&c!=0,"Original creation query");return c;}
 static string Quote(string v){var b=new StringBuilder("\"");int n=0;foreach(char c in v){if(c=='\\'){n++;continue;}b.Append('\\',c=='"'?n*2+1:n);b.Append(c);n=0;}return b.Append('\\',n*2).Append('"').ToString();}
 static string Hash(string p){using(var s=File.OpenRead(p))using(var h=System.Security.Cryptography.SHA256.Create())return BitConverter.ToString(h.ComputeHash(s)).Replace("-","").ToLowerInvariant();}
 static void Plain(string path){Check(Path.IsPathRooted(path),"Absolute path required");for(string p=Path.GetFullPath(path);!String.IsNullOrEmpty(p);p=Path.GetDirectoryName(p))if(File.Exists(p)||Directory.Exists(p))Check((File.GetAttributes(p)&FileAttributes.ReparsePoint)==0,"Reparse path rejected");}
 sealed class Child:IDisposable {
  public PI pin;public IntPtr output,error;public long creation;
  public void Dispose(){if(pin.process!=IntPtr.Zero){if(WaitForSingleObject(pin.process,0)!=0){Check(TerminateProcess(pin.process,74),"Owned failure terminate");Check(WaitForSingleObject(pin.process,5000)==0,"Owned failure reap");}CloseHandle(pin.process);pin.process=IntPtr.Zero;}if(pin.thread!=IntPtr.Zero)CloseHandle(pin.thread);if(output!=IntPtr.Zero)CloseHandle(output);if(error!=IntPtr.Zero)CloseHandle(error);}
 }
 static Child Start(string exe,string[] args,string desktop,IntPtr job){
  var child=new Child();IntPtr ow=IntPtr.Zero,ew=IntPtr.Zero,input=IntPtr.Zero,attrs=IntPtr.Zero,handles=IntPtr.Zero;bool initialized=false;
  try{SA sa=new SA{size=Marshal.SizeOf(typeof(SA)),inherit=1};Check(CreatePipe(out child.output,out ow,ref sa,4096),"Owned stdout pipe");Check(CreatePipe(out child.error,out ew,ref sa,4096),"Owned stderr pipe");Check(SetHandleInformation(child.output,1,0)&&SetHandleInformation(child.error,1,0),"Parent-only read pipes");input=CreateFileW("NUL",0x80000000,3,ref sa,3,0,IntPtr.Zero);Check(input!=IntPtr.Zero&&input!=new IntPtr(-1),"Owned null input");IntPtr size=IntPtr.Zero;InitializeProcThreadAttributeList(IntPtr.Zero,1,0,ref size);Check(size.ToInt64()>0&&size.ToInt64()<65536,"Attribute bound");attrs=Marshal.AllocHGlobal(size);Check(InitializeProcThreadAttributeList(attrs,1,0,ref size),"Initialize allowlist");initialized=true;IntPtr[] list=new[]{input,ow,ew};handles=Marshal.AllocHGlobal(IntPtr.Size*list.Length);Marshal.Copy(list,0,handles,list.Length);Check(UpdateProcThreadAttribute(attrs,0,new IntPtr(0x20002),handles,new IntPtr(IntPtr.Size*list.Length),IntPtr.Zero,IntPtr.Zero),"Exact inherited allowlist");var si=new SIX();si.startup.cb=Marshal.SizeOf(typeof(SIX));si.startup.desktop=desktop;si.startup.flags=0x100;si.startup.input=input;si.startup.output=ow;si.startup.error=ew;si.attributes=attrs;var command=new StringBuilder(Quote(exe));foreach(string a in args)command.Append(' ').Append(Quote(a));Check(CreateProcessW(exe,command,IntPtr.Zero,IntPtr.Zero,true,0x08080004,IntPtr.Zero,Path.GetDirectoryName(exe),ref si,out child.pin),"Owned suspended fixture");Check(AssignProcessToJobObject(job,child.pin.process),"Owned observer Job binding");child.creation=Creation(child.pin.process);Check(ResumeThread(child.pin.thread)!=0xffffffff,"Resume fixture");return child;}catch{child.Dispose();throw;}finally{if(initialized)DeleteProcThreadAttributeList(attrs);if(attrs!=IntPtr.Zero)Marshal.FreeHGlobal(attrs);if(handles!=IntPtr.Zero)Marshal.FreeHGlobal(handles);foreach(IntPtr h in new[]{ow,ew,input})if(h!=IntPtr.Zero&&h!=new IntPtr(-1))CloseHandle(h);}
 }
 static string Line(Child c,int seconds){var watch=Stopwatch.StartNew();var data=new List<byte>();var errors=new List<byte>();while(watch.Elapsed.TotalSeconds<seconds){foreach(var pair in new[]{new[]{c.output,new IntPtr(0)},new[]{c.error,new IntPtr(1)}}){uint available;if(!PeekNamedPipe(pair[0],IntPtr.Zero,0,IntPtr.Zero,out available,IntPtr.Zero)){Check(Marshal.GetLastWin32Error()==109,"Owned pipe query");continue;}if(available==0)continue;byte[] block=new byte[Math.Min(available,128u)];uint read;Check(ReadFile(pair[0],block,(uint)block.Length,out read,IntPtr.Zero),"Owned pipe read");var target=pair[1]==IntPtr.Zero?data:errors;for(int i=0;i<read;i++)target.Add(block[i]);Check(target.Count<=4096,"Handshake output bound");if(pair[1]==IntPtr.Zero&&data.Contains(10)){int end=data.IndexOf(10);Check(end==data.Count-1,"Unexpected queued stdout");return new UTF8Encoding(false,true).GetString(data.ToArray()).TrimEnd('\r','\n');}}if(WaitForSingleObject(c.pin.process,0)==0){uint remaining;bool queued=PeekNamedPipe(c.output,IntPtr.Zero,0,IntPtr.Zero,out remaining,IntPtr.Zero)&&remaining>0;if(!queued)queued=PeekNamedPipe(c.error,IntPtr.Zero,0,IntPtr.Zero,out remaining,IntPtr.Zero)&&remaining>0;Check(queued,"Fixture exited before handshake; stderr="+Encoding.UTF8.GetString(errors.ToArray()));}Thread.Sleep(10);}throw new Exception("Handshake deadline");}
 static void Save(string path,object value){File.WriteAllText(path,new JavaScriptSerializer().Serialize(value),new UTF8Encoding(false));}
 static int Main(string[] a){IntPtr desktop=IntPtr.Zero,job=IntPtr.Zero;string output=null;var result=new Dictionary<string,object>();result["status"]="FAIL";
 try{Check(a.Length==2||(a.Length==3&&a[2]=="--preserve"),"Arguments fixture-executable fresh-output [--preserve]");bool preserve=a.Length==3;string exe=Path.GetFullPath(a[0]);output=Path.GetFullPath(a[1]);Plain(exe);Plain(output);Check(File.Exists(exe)&&!File.Exists(output)&&!Directory.Exists(output),"Fresh owned output required");Directory.CreateDirectory(output);string wrapper=Path.Combine(output,"dlpad-paired-parent-crash-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(wrapper);string root=Path.Combine(wrapper,"owned-fixture");string before=Input();result["input_before"]=before;string binaryHash=Hash(exe);result["fixture_sha256_before"]=binaryHash;string name="dlpad-paired-crash-"+Guid.NewGuid().ToString("N");desktop=CreateDesktop(name,IntPtr.Zero,IntPtr.Zero,0,0x83,IntPtr.Zero);Check(desktop!=IntPtr.Zero,"Private desktop unavailable");job=CreateJobObject(IntPtr.Zero,null);Check(job!=IntPtr.Zero,"Owned Job");Limits limits=new Limits();limits.basic.flags=0x2000;Check(SetInformationJobObject(job,9,ref limits,(uint)Marshal.SizeOf(typeof(Limits))),"Own kill-on-close Job");
 using(Child parent=Start(exe,new[]{"paired-parent",root},name,job)){
  string raw=Line(parent,20);File.WriteAllText(Path.Combine(output,"ready.json"),raw+"\n");var ready=new JavaScriptSerializer().Deserialize<Dictionary<string,object>>(raw);Check(Convert.ToInt32(ready["schema"])==1&&(string)ready["phase"]=="paired-tool-started","Readiness schema");Check(Convert.ToInt64(ready["parent_creation"])==parent.creation,"Original parent creation");result["parent_pid_display_only"]=parent.pin.pid;result["parent_creation"]=parent.creation;Check(TerminateProcess(parent.pin.process,73),"Original parent-only termination");Check(WaitForSingleObject(parent.pin.process,5000)==0,"Parent bounded wait");uint code;Check(GetExitCodeProcess(parent.pin.process,out code)&&code==73,"Explicit parent exit status");result["parent_exit"]=code;
 }
 using(Child inspect=Start(exe,new[]{preserve?"paired-preserve":"paired-inspect",root},name,job)){string raw=Line(inspect,20);File.WriteAllText(Path.Combine(output,"inspection.json"),raw+"\n");var proof=new JavaScriptSerializer().Deserialize<Dictionary<string,object>>(raw);Check(Convert.ToInt32(proof["schema"])==1&&Convert.ToBoolean(proof["source_foreign_preserved"])&&(preserve?((string)proof["phase"]=="paired-preserved"&&Convert.ToBoolean(proof["both_receipts_ready"])&&!Convert.ToBoolean(proof["recovery_called"])):((string)proof["phase"]=="paired-recovery-evidence"&&Convert.ToBoolean(proof["both_receipts_valid"])&&Convert.ToBoolean(proof["managed_recovered"])&&Convert.ToBoolean(proof["cookie_recovered"]))),"Original independent receipt inspection");Check(WaitForSingleObject(inspect.pin.process,5000)==0,"Inspector bounded exit");uint code;Check(GetExitCodeProcess(inspect.pin.process,out code)&&code==0,"Inspector success");result["inspection"]=proof;}
 Check(Hash(exe)==binaryHash,"Fixture immutable hash");result["fixture_sha256_after"]=Hash(exe);result["status"]="PASS";
 }catch(Exception e){result["error"]=e.GetType().Name+": "+e.Message;}
 finally{if(job!=IntPtr.Zero){Accounting info;bool naturallyEmpty=false;for(int i=0;i<200;i++){if(QueryInformationJobObject(job,1,out info,(uint)Marshal.SizeOf(typeof(Accounting)),IntPtr.Zero)&&info.active==0){naturallyEmpty=true;break;}Thread.Sleep(50);}result["owned_job_naturally_empty"]=naturallyEmpty;if(!naturallyEmpty){result["status"]="FAIL";result["owned_job_failure_cleanup"]=TerminateJobObject(job,74);}bool empty=false;for(int i=0;i<100;i++){if(QueryInformationJobObject(job,1,out info,(uint)Marshal.SizeOf(typeof(Accounting)),IntPtr.Zero)&&info.active==0){empty=true;break;}Thread.Sleep(50);}result["owned_job_empty"]=empty;if(!empty)result["status"]="FAIL";CloseHandle(job);}if(desktop!=IntPtr.Zero){bool closed=CloseDesktop(desktop);result["private_desktop_closed"]=closed;if(!closed)result["status"]="FAIL";}try{string after=Input();result["input_after"]=after;result["input_desktop_unchanged"]=result.ContainsKey("input_before")&&after==(string)result["input_before"];if(!(bool)result["input_desktop_unchanged"])result["status"]="FAIL";}catch{result["status"]="FAIL";}if(output!=null&&Directory.Exists(output))Save(Path.Combine(output,"result.json"),result);}
 Console.WriteLine(new JavaScriptSerializer().Serialize(result));return (string)result["status"]=="PASS"?0:2;
 }
}
